/**
 * Emit the synchronous `tool_effect_before` reservation for one admitted tool invocation.
 * Handlers must be synchronous: their first throw propagates and blocks the invocation.
 * Called by the tool wrapper immediately before definition.execute, after every
 * tool_call blocker and scheduler skip.
 */
emitToolEffectBefore(event) {
    for (const ext of this.extensions) {
        const handlers = ext.handlers.get("tool_effect_before");
        if (!handlers || handlers.length === 0)
            continue;
        for (const handler of handlers) {
            const handlerResult = handler(event, this.createContext(ext.path));
            if (handlerResult !== undefined && typeof handlerResult.then === "function") {
                throw new Error("tool_effect_before handlers must be synchronous");
            }
        }
    }
}
