 * Emit the single `tool_effect_settled` record for one admitted tool invocation,
 * derived from the actual definition promise outcome. Handler failures are reported
 * through the extension error channel and never change the tool result.
 */
async emitToolEffectSettled(event) {
    for (const ext of this.extensions) {
        const handlers = ext.handlers.get("tool_effect_settled");
        if (!handlers || handlers.length === 0)
            continue;
        for (const handler of handlers) {
            try {
                await handler(event, this.createContext(ext.path));
            }
            catch (err) {
                const message = err instanceof Error ? err.message : String(err);
                const stack = err instanceof Error ? err.stack : undefined;
                this.emitError({
                    extensionPath: ext.path,
                    event: "tool_effect_settled",
                    error: message,
                    stack,
                });
